package pzvrphysicality;
import java.util.*;import local.pzvr.*;import org.joml.Quaternionf;import viewpoint.core.Frame;import viewpointvr.physics.CollisionShape;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;

/** Source-neutral immutable geometry offers. No native instance, mesh, wrist or drawer is invented here. */
public final class HeldContactExternal {
 public interface Source {List<Offer> targets(Frame frame,IsoPlayer actor,long now);boolean current(Offer offer,long now);boolean corrected(Offer offer,float[] worldPose);void clear();}
 public record Offer(Source source,Object receipt,IsoPlayer actor,InventoryItem item,int side,Object scene,XrBackend.Frame input,long rigGeneration,long sourceEpoch,long time,double units,float mass,CollisionShape shape,Object geometryIdentity,float[] pose){
  public Offer{Objects.requireNonNull(source);Objects.requireNonNull(receipt);Objects.requireNonNull(actor);Objects.requireNonNull(item);Objects.requireNonNull(scene);Objects.requireNonNull(input);Objects.requireNonNull(shape);Objects.requireNonNull(geometryIdentity);if(side<0||side>1||rigGeneration<0||sourceEpoch<0||time<0||!Double.isFinite(units)||units<.25||units>4||!Float.isFinite(mass)||mass<.01||mass>20||shape.staticOnly()||shape.boxes().length!=0||shape.vertices().length>48000||shape.faces().length>96000)throw new IllegalArgumentException("External held offer");pose=pose.clone();MoveableGeometry.world(pose);}public float[] pose(){return pose.clone();}
 }
 private static final IdentityHashMap<Source,Long> sources=new IdentityHashMap<>();private static long revision;
 /** Never invoke a provider while holding this registry monitor. */
 public static boolean register(Source source,boolean enabled){Objects.requireNonNull(source);synchronized(sources){if(enabled&&sources.size()>=3&&!sources.containsKey(source))return false;revision++;if(enabled)sources.put(source,revision);else sources.remove(source);}if(!enabled)clear(source);return true;}
 public static void changed(Source source){synchronized(sources){if(sources.containsKey(source))revision++;}}
 public static long version(Source source){synchronized(sources){return sources.getOrDefault(source,-1L);}}
 public static long revision(){synchronized(sources){return revision;}}
 private static List<Source> snapshot(){var result=new ArrayList<Source>();result.add(HeldContactPack.source());synchronized(sources){result.addAll(sources.keySet());}return List.copyOf(result);}
 public static List<Offer> targets(Frame frame,IsoPlayer actor,long now){if(!HeldContactDriver.enabled()||frame==null||actor==null)return List.of();var result=new ArrayList<Offer>();for(var source:snapshot())try{var offered=source.targets(frame,actor,now);if(offered==null||offered.size()>2)continue;for(var offer:offered)if(offer!=null&&offer.source==source&&offer.actor==actor&&offer.scene==frame.scene&&current(offer,now))result.add(offer);}catch(RuntimeException|LinkageError unavailable){clear(source);}return List.copyOf(result);}
 public static boolean current(Offer offer,long now){if(offer==null||!HeldContactDriver.enabled()||!HeldContactDriver.admitsScene(offer.scene,offer.actor,now)||now<offer.time||now-offer.time>150_000_000L||!HeldContactCapture.prop(offer.actor,offer.item,offer.side))return false;boolean known=offer.source==HeldContactPack.source();if(!known)synchronized(sources){known=sources.containsKey(offer.source);}var rig=WorldRigCapture.latest;var input=Engine.latestInput;var hand=input==null?null:offer.side==0?input.left():input.right();if(hand==null||!hand.tracked()||hand.grip()==null)return false;if(!known||input!=offer.input||!input.focused()||rig==null||rig.actor()!=offer.actor||rig.scene()!=offer.scene||rig.generation()!=offer.rigGeneration||!rig.fresh(now)||input.time()!=rig.inputTime()||rig.hand(offer.side)==null||Math.abs(rig.hand(offer.side).units()-offer.units)>.0001)return false;try{return offer.source.current(offer,now);}catch(RuntimeException|LinkageError unavailable){return false;}}
 public static boolean constrain(Offer offer,HeldContactWorld.Response response,double metres){if(!current(offer,System.nanoTime())||response==null||!Double.isFinite(metres)||metres<=0)return false;var shift=response.translation();double length=0;for(float value:shift){if(!Float.isFinite(value))return false;length+=value*value;}double limit=Math.min(.0399,metres)*offer.units,scale=length>limit*limit?limit/Math.sqrt(length):1;var pose=offer.pose();for(int n=0;n<3;n++)pose[n]+=(float)(shift[n]*scale);var delta=HeldContactRotation.difference(response);if(delta==null)return false;double angle=HeldContactRotation.angle(response),maximum=Math.toRadians(14.9);if(angle>maximum)delta=new Quaternionf().slerp(delta,(float)(maximum/angle));delta.mul(new Quaternionf(pose[3],pose[4],pose[5],pose[6])).normalize();pose[3]=delta.x;pose[4]=delta.y;pose[5]=delta.z;pose[6]=delta.w;try{return current(offer,System.nanoTime())&&offer.source.corrected(offer,pose);}catch(RuntimeException|LinkageError unavailable){return false;}}
 private static void clear(Source source){try{source.clear();}catch(RuntimeException|LinkageError ignored){}}
 public static void clear(){for(var source:snapshot())clear(source);}
 private HeldContactExternal(){}
}
